 public static final String INSERT_INBOX_EVENTS_50="INSERT INTO ingestion.inbox_events(consumer_name,event_id) VALUES ('catalog-result',?) ON CONFLICT DO NOTHING";
 public static final String UPDATE_IMPORT_ITEMS_51="UPDATE ingestion.import_items SET status='APPLIED',resulting_place_id=?,resulting_catalog_version=?,error_code=NULL,error_detail=NULL,version=version+1,updated_at=now() WHERE command_id=?";
 public static final String INSERT_SOURCE_PLACE_LINKS_52="INSERT INTO ingestion.source_place_links(link_id,source_id,external_id,place_id,last_hash,catalog_version,confidence) VALUES (?,?,?,?,?,?,1) ON CONFLICT(source_id,external_id) DO UPDATE SET place_id=EXCLUDED.place_id,last_hash=EXCLUDED.last_hash,catalog_version=EXCLUDED.catalog_version,last_seen_at=now() WHERE ingestion.source_place_links.catalog_version<=EXCLUDED.catalog_version";
